-- Ejecutar completo en Supabase > SQL Editor antes de usar la aplicación.
create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','utr');
create table public.unidades (id uuid primary key default gen_random_uuid(), nombre text not null unique);
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, nombre_completo text not null default '', unidad_id uuid references public.unidades(id), rol public.user_role not null default 'utr', created_at timestamptz not null default now());
create table public.ambitos (id uuid primary key default gen_random_uuid(), numero integer not null unique, nombre text not null unique);
create table public.lineamientos (id uuid primary key default gen_random_uuid(), ambito_id uuid not null references public.ambitos(id) on delete cascade, codigo text not null unique, nombre text not null);
create table public.objetivos (id uuid primary key default gen_random_uuid(), lineamiento_id uuid not null references public.lineamientos(id) on delete cascade, codigo text not null unique, descripcion text not null);
create table public.estados (id uuid primary key default gen_random_uuid(), nombre text not null unique, orden integer not null default 0);
create table public.proyectos (id uuid primary key default gen_random_uuid(), nombre text not null unique, ambito_id uuid references public.ambitos(id), lineamiento_id uuid references public.lineamientos(id), objetivo_id uuid references public.objetivos(id), unidad_id uuid references public.unidades(id), presupuesto numeric not null default 0 check(presupuesto>=0), anio_inicio integer, anio_termino integer, meta numeric default 0 check(meta between 0 and 1), meta_descripcion text, estado_id uuid references public.estados(id), indicador_seguimiento text, financiamiento text, formulador text, tecnico text, direccion text, observaciones text, avance numeric not null default 0 check(avance between 0 and 1), diferencia numeric not null default 1 check(diferencia between 0 and 1), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tareas (id uuid primary key default gen_random_uuid(), proyecto_id uuid not null references public.proyectos(id) on delete cascade, nombre text not null, orden integer not null default 0, avance numeric not null default 0 check(avance between 0 and 1), ponderador numeric not null default 0 check(ponderador between 0 and 1), presupuesto numeric not null default 0 check(presupuesto>=0), pagado boolean not null default false, comprobante text, pendiente numeric not null default 1 check(pendiente between 0 and 1), av_pond numeric not null default 0, pnd_pond numeric not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint comprobante_si_pagado check((pagado and nullif(trim(coalesce(comprobante,'')),'') is not null) or (not pagado and comprobante is null)));
create index tareas_proyecto_idx on public.tareas(proyecto_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and rol='admin')$$;
create or replace function public.can_edit_project(pid uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_admin() or exists(select 1 from public.proyectos p join public.profiles pr on pr.id=auth.uid() where p.id=pid and p.unidad_id=pr.unidad_id)$$;
create or replace function public.sync_task_calculations() returns trigger language plpgsql as $$begin new.pendiente:=1-new.avance;new.av_pond:=new.avance*new.ponderador;new.pnd_pond:=new.pendiente*new.ponderador;new.updated_at:=now();if not new.pagado then new.comprobante:=null;end if;return new;end$$;
create or replace function public.check_task_budget() returns trigger language plpgsql as $$declare total numeric; limit_value numeric; begin select coalesce(sum(presupuesto),0),coalesce((select presupuesto from public.proyectos where id=new.proyecto_id),0) into total,limit_value from public.tareas where proyecto_id=new.proyecto_id and id is distinct from new.id; if total+new.presupuesto>limit_value then raise exception 'El presupuesto de tareas supera el presupuesto del proyecto'; end if; return new;end$$;
create or replace function public.recalculate_project(pid uuid) returns void language plpgsql as $$begin update public.proyectos set avance=coalesce((select sum(av_pond) from public.tareas where proyecto_id=pid),0),diferencia=1-coalesce((select sum(av_pond) from public.tareas where proyecto_id=pid),0),updated_at=now() where id=pid;end$$;
create or replace function public.refresh_project_progress() returns trigger language plpgsql as $$begin perform public.recalculate_project(coalesce(new.proyecto_id,old.proyecto_id));return coalesce(new,old);end$$;
create trigger task_calc before insert or update on public.tareas for each row execute function public.sync_task_calculations();
create trigger task_budget before insert or update of presupuesto,proyecto_id on public.tareas for each row execute function public.check_task_budget();
create trigger task_progress after insert or update or delete on public.tareas for each row execute function public.refresh_project_progress();
create or replace function public.validate_project_hierarchy() returns trigger language plpgsql as $$begin if new.lineamiento_id is not null and not exists(select 1 from public.lineamientos where id=new.lineamiento_id and ambito_id=new.ambito_id) then raise exception 'El lineamiento no pertenece al ámbito';end if;if new.objetivo_id is not null and not exists(select 1 from public.objetivos where id=new.objetivo_id and lineamiento_id=new.lineamiento_id) then raise exception 'El objetivo no pertenece al lineamiento';end if;new.updated_at:=now();return new;end$$;
create trigger project_hierarchy before insert or update on public.proyectos for each row execute function public.validate_project_hierarchy();
alter table public.profiles enable row level security;alter table public.unidades enable row level security;alter table public.ambitos enable row level security;alter table public.lineamientos enable row level security;alter table public.objetivos enable row level security;alter table public.estados enable row level security;alter table public.proyectos enable row level security;alter table public.tareas enable row level security;
create policy "authenticated read profiles" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "admin manage profiles" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "authenticated read unidades" on public.unidades for select to authenticated using(true);create policy "admin manage unidades" on public.unidades for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "authenticated read ambitos" on public.ambitos for select to authenticated using(true);create policy "admin manage ambitos" on public.ambitos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "authenticated read lineamientos" on public.lineamientos for select to authenticated using(true);create policy "admin manage lineamientos" on public.lineamientos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "authenticated read objetivos" on public.objetivos for select to authenticated using(true);create policy "admin manage objetivos" on public.objetivos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "authenticated read estados" on public.estados for select to authenticated using(true);create policy "admin manage estados" on public.estados for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "authenticated read proyectos" on public.proyectos for select to authenticated using(true);create policy "admin manage proyectos" on public.proyectos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "read tareas" on public.tareas for select to authenticated using(true);create policy "unit manage own tareas" on public.tareas for all to authenticated using(public.can_edit_project(proyecto_id)) with check(public.can_edit_project(proyecto_id));
